def get_base64_image(image_path):
    if os.path.exists(image_path):
        with open(image_path, "rb") as img_file:
            return base64.b64encode(img_file.read()).decode()
    return ""

logo_base64 = get_base64_image(os.path.join(os.path.dirname(os.path.abspath(__file__)), "logo_poltekad.png"))
logo_img_tag = f'<img src="data:image/png;base64,{logo_base64}" class="brand-logo" alt="Logo Poltekad">' if logo_base64 else '<div style="font-size:45px; margin-bottom:10px;">🎖️</div>'

