def hitung_nilai(hadir, kuis, uts, uas):
    if None in (hadir, kuis, uts, uas):
        return None, "-", 0.0
    na = (hadir * 0.10) + (kuis * 0.20) + (uts * 0.30) + (uas * 0.40)
    if na >= 85: grade, bobot = "A", 4.0
    elif na >= 80: grade, bobot = "A-", 3.7
    elif na >= 75: grade, bobot = "B+", 3.3
    elif na >= 70: grade, bobot = "B", 3.0
    elif na >= 65: grade, bobot = "B-", 2.7
    elif na >= 60: grade, bobot = "C+", 2.3
    elif na >= 55: grade, bobot = "C", 2.0
    elif na >= 50: grade, bobot = "D", 1.0
    else: grade, bobot = "E", 0.0
    return round(na, 1), grade, bobot

