def generate_excel_template():
    output = BytesIO()
    with pd.ExcelWriter(output, engine='openpyxl') as writer:
        df_format = pd.DataFrame({
            "No": [1, 2, 3, 4, 5],
            "NIM": ["202409021-E", "202409022-E", "202409023-E", "202409024-E", "202409025-E"],
            "Nama Mahasiswa": ["Andi Achmad Kurniawan Syam", "M. Azam Yasir", "Didik Setiyawan", "Hendry Hutauruk", "Farid Cahyono"],
            "Hadir (10%)": [85, 90, 80, 85, 90],
            "Kuis (20%)": [80, 85, 75, 80, 85],
            "UTS (30%)": [82, 88, 78, 83, 86],
            "UAS (40%)": [85, 87, 80, 84, 88]
        })
        df_format.to_excel(writer, sheet_name="Format Penilaian", index=False)
    output.seek(0)
    return output.getvalue()

def generate_pdf_panduan():
    buffer = BytesIO()
    doc = SimpleDocTemplate(buffer, pagesize=A4, leftMargin=15 * mm, rightMargin=15 * mm, topMargin=15 * mm, bottomMargin=15 * mm)
    story = []
    
    story.append(Paragraph("<b>KODIKLAT TNI ANGKATAN DARAT</b>", ParagraphStyle('SubHead1', fontName='Helvetica', fontSize=7.5, leading=9, alignment=0)))
    story.append(Paragraph("<b>POLTEKAD</b>", ParagraphStyle('SubHead2', fontName='Helvetica-Bold', fontSize=8.5, leading=10, alignment=0)))
